  INDEX `idx_team_id`(`team_id`) USING BTREE,
  INDEX `idx_shift_id`(`shift_id`) USING BTREE,
  INDEX `idx_scheduled_date`(`scheduled_date`) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id`) USING BTREE
